def preCoordinate (D : ConstructionData 𝕜) (n : ℕ) : PreSpace D →L[𝕜] 𝕜 :=
  (Finsupp.lapply n : PreSpace D →ₗ[𝕜] 𝕜).mkContinuous 1
    (fun x => by simpa only [one_mul] using PreSpace.norm_apply_le x n)

